/*
 * A192523  Monotonic ordering of set S generated by these rules: if x and y
 *          are in S then 2xy-x-y is in S, and 2 is in S.
 * https://oeis.org/A192523
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 5, u16 n <= 47, u32 n <= 47, u64 n <= 47, u128 n <= 47,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  OEIS A192523 – Monotonic ordering of the set S generated by  
    x, y ∈ S  →  2xy – x – y ∈ S,  starting with 2.  

    The set is represented by the odd numbers v = 2x – 1.  
    v(1) = 3, and for i, j ≥ 1  :  v_new = v[i] * v[j] – 2.  
    The sequence values are a(n) = (v(n) + 1) / 2. */

#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

/* ------------------------------------------------------------ */
/*  Min‑heap of candidate values of the form v[i]*v[j] – 2.     */
/* ------------------------------------------------------------ */
typedef struct {
    seq_t val;      /* candidate value */
    size_t i;       /* index i (first operand)   */
    size_t j;       /* index j (second operand)  */
} node_t;

static node_t *heap      = NULL;
static size_t heap_sz    = 0;
static size_t heap_cap   = 0;

/* Push a node onto the binary heap. */
static void heap_push(node_t n)
{
    if (heap_sz == heap_cap) {
        heap_cap = (heap_cap == 0) ? 4 : heap_cap << 1;
        heap = (node_t *)realloc(heap, heap_cap * sizeof(node_t));
    }
    size_t k = heap_sz++;
    heap[k] = n;
    while (k > 0) {
        size_t p = (k - 1) >> 1;
        if (heap[p].val <= heap[k].val) break;
        node_t tmp = heap[p];
        heap[p] = heap[k];
        heap[k] = tmp;
        k = p;
    }
}

/* Pop the minimum node from the heap. */
static node_t heap_pop(void)
{
    node_t top = heap[0];
    heap_sz--;
    if (heap_sz > 0) {
        heap[0] = heap[heap_sz];
        size_t k = 0;
        while (1) {
            size_t l = (k << 1) + 1;
            size_t r = l + 1;
            if (l >= heap_sz) break;
            size_t child = (r < heap_sz && heap[r].val < heap[l].val) ? r : l;
            if (heap[k].val <= heap[child].val) break;
            node_t tmp = heap[k];
            heap[k] = heap[child];
            heap[child] = tmp;
            k = child;
        }
    }
    return top;
}

/* ------------------------------------------------------------ */
/*  Storage for the growing sequence of v-values.               */
/* ------------------------------------------------------------ */
static seq_t *v_cache = NULL;
static size_t v_sz    = 0;
static size_t v_cap   = 0;

/* Ensure that v_cache contains at least n terms (1‑based index). */
static void ensure_terms(idx_t n)
{
    if ((size_t)n <= v_sz) return;                /* already computed */

    /* Initialise with the first element v(1) = 3. */
    if (v_sz == 0) {
        v_cap = 4;
        v_cache = (seq_t *)realloc(v_cache, v_cap * sizeof(seq_t));
        v_cache[0] = (seq_t)3;
        v_sz = 1;
    }

    /* Initialise heap with the first candidate from (1,1). */
    if (heap_sz == 0) {
        heap_cap = 4;
        heap = (node_t *)realloc(heap, heap_cap * sizeof(node_t));
        heap[0] = (node_t){(seq_t)((v_cache[0] * v_cache[0]) - (seq_t)2), 0, 0};
        heap_sz = 1;
    }

    /* Keep track of the last added value to skip duplicates. */
    seq_t last_val = (seq_t)0;
    bool first_val = true;

    while (v_sz < (size_t)n) {
        node_t cur = heap_pop();

        /* Add the value if it is new. */
        bool added = false;
        if (first_val || cur.val != last_val) {
            if (v_sz == v_cap) {
                v_cap = (v_cap == 0) ? 4 : v_cap << 1;
                v_cache = (seq_t *)realloc(v_cache, v_cap * sizeof(seq_t));
            }
            v_cache[v_sz++] = cur.val;
            last_val = cur.val;
            added = true;
            first_val = false;
        }

        /* Generate the next candidate for the same pair (i,j). */
        if (cur.j + 1 < v_sz) {
            seq_t newval = (seq_t)((v_cache[cur.i] * v_cache[cur.j + 1]) - (seq_t)2);
            heap_push((node_t){newval, cur.i, cur.j + 1});
        }

        /* If a new value was added, insert its self‑pair for future use. */
        if (added) {
            size_t k = v_sz - 1;
            seq_t newself = (seq_t)((v_cache[k] * v_cache[k]) - (seq_t)2);
            heap_push((node_t){newself, k, k});
        }
    }
}

/* ------------------------------------------------------------ */
/*  Public API: returns the nth term of A192523 (1‑based index).*/
/* ------------------------------------------------------------ */
seq_t a(idx_t n)
{
    if (n < (idx_t)1) return (seq_t)0;   /* undefined index */
    ensure_terms(n);
    /* a(n) = (v(n) + 1) / 2 */
    return (v_cache[n - 1] + (seq_t)1) / (seq_t)2;
}
